script:
function setupForm({ doc }) {
  if (doc.status !== "Qualified") return {actions: []};
  return {actions: [{
    label: "Create / Open Tenant Deal",
    onClick: async () => {
      const result = await call("truegroup_property.services.onboarding.create_deal", {lead_name: doc.name});
      window.location.href = "/desk/crm-deal/" + encodeURIComponent(result.deal);
    }
  }]};
}

function setupForm({ doc }) {
  if (doc.status !== "Won") return {actions: []};
  return {actions: [{
    label: "Review / Open Customer",
    onClick: async () => {
      const result = await call("truegroup_property.services.onboarding.prepare_customer", {deal_name: doc.name});
      window.location.href = result.customer
        ? "/desk/customer/" + encodeURIComponent(result.customer)
        : "/desk/customer/new-customer-1?crm_deal=" + encodeURIComponent(doc.name);
    }
  }, {
    label: "Create / Open Service Request",
    onClick: async () => {
      const result = await call("truegroup_property.services.onboarding.create_service_request", {deal_name: doc.name});
      window.location.href = "/desk/utility-service-request/" + encodeURIComponent(result.service_request);
    }
  }]};
}
